def render_html(workspace):
    bootstrap = {"workspace_id": workspace["workspace_id"]}
    page = HTML.replace("__BOOT__", json.dumps(bootstrap,ensure_ascii=False).replace("<","\\u003c").replace(">","\\u003e").replace("&","\\u0026"))
    script = re.search(r"<script>([\s\S]*?)</script>",page).group(1)
    style = re.search(r"<style>([\s\S]*?)</style>",page).group(1)
    digest = lambda text: base64.b64encode(hashlib.sha256(text.encode("utf-8")).digest()).decode("ascii")
    policy = "default-src 'none'; script-src 'sha256-"+digest(script)+"'; style-src 'sha256-"+digest(style)+"'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
    return page.replace("__CSP__",policy)
